import {seasonalDatasetText} from './hybrid-learning.js?v=20261105-quality2';
import {NAME_LANGUAGES,languageLabel} from './name-languages.js?v=20261101-scientific1';

export const INFO_REVIEWED='2026-11-05';
export const SOURCE_TITLES_EN=Object.freeze({
 'https://support.ebird.org/en/support/solutions/articles/48000804865':'eBird: multilingual bird names and four-letter codes (30 October 2025)',
 'https://www.birds.cornell.edu/clementschecklist/download/':'Cornell: eBird/Clements v2025 taxonomy downloads',
 'https://www.dda-web.de/downloads/publications/statusreports/vid_bestandssituation_2025.pdf':'DDA: Birds in Germany — Population Status 2025 (breeding birds pp. 36–44; waterbirds pp. 66–68)',
 'https://www.do-g.de/fileadmin/Ablage/DOG/Fachkommissionen/Kommission_Artenliste/Dokumente/Barthel_Kr%C3%BCger_2019_Liste_der_V%C3%B6gel_Deutschlands_3.2.pdf':'DO-G: German bird checklist, version 3.2 (2019); regular winter visitors and passage migrants'
});
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const download=(url,label)=>`<a href="${esc(url)}" download>${esc(label)}</a>`;
export function informationFacts({birds,photos,regions}){
 const images=Object.values(photos).flatMap(p=>[p,...p.additional||[]]);
 const comparison=kind=>Object.values(photos).filter(p=>new Set([p,...p.additional||[]].filter(x=>(x.mediaType||'photo')===kind).flatMap(x=>x.sexes||[])).size===2).length;
 const lists=regions?.regions.flatMap(r=>[r.all,r.recent].filter(Boolean))||[];
 const stamps=lists.map(x=>x.updatedAt).sort((a,b)=>Date.parse(a)-Date.parse(b));
 return {species:birds.length,photoCount:images.filter(p=>(p.mediaType||'photo')==='photo').length,illustrationCount:images.filter(p=>p.mediaType==='illustration').length,photoComparisons:comparison('photo'),illustrationComparisons:comparison('illustration'),regionCount:regions?.regions.length||0,listCount:lists.length,oldest:stamps[0],newest:stamps.at(-1)};
}
export function renderInformation({english,birds,meta,germanNamesMeta={},photos={},regions=null,seasonal=null}){
 const locale=english?'en-GB':'de-DE',f=informationFacts({birds,photos,regions});
 const choose=(de,en)=>english?en:de;
 const date=value=>new Date(value).toLocaleDateString(locale,{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
 const stamp=value=>new Date(value).toLocaleString(locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';
 const built=/^\d{2}\.\d{2}\.\d{4}$/.test(meta.built)?date(meta.built.split('.').reverse().join('-')):esc(meta.built);
 const languages=NAME_LANGUAGES.map(l=>esc(languageLabel(l.code,english?'en':'de'))).join(', ');
 const countryCoverage=regions?.countries.map(c=>{
  const count=regions.regions.filter(r=>r.parentCode===c.code).length,local=regions.regions.filter(r=>r.country===c.code&&r.code.split('-').length===3).length;
  const type=choose(c.code==='DE'?(count===1?'Bundesland':'Bundesländer'):c.code==='NL'?(count===1?'Provinz':'Provinzen'):c.code==='GB'?(count===1?'Landesteil':'Landesteile'):(count===1?'Region':'Regionen'),c.code==='DE'?(count===1?'federal state':'federal states'):c.code==='NL'?(count===1?'province':'provinces'):c.code==='GB'?(count===1?'constituent country':'constituent countries'):(count===1?'region':'regions'));
  return `${esc(english?c.nameEn:c.nameDe)}: ${count} ${type}${local?choose(` und ${local} lokale eBird-${local===1?'Region':'Regionen'}`,` and ${local} local eBird ${local===1?'region':'regions'}`):''}`;
 }).join('; ');
 const freshness=f.listCount?choose(`${f.regionCount} Gebiete einschließlich Länderlisten; ${f.listCount} verfügbare Artenlisten. Letzte erfolgreiche Listenaktualisierungen: `,`${f.regionCount} areas including country-wide lists; ${f.listCount} available species lists. Last successful list updates: `)+(f.oldest===f.newest?stamp(f.newest):`${stamp(f.oldest)} – ${stamp(f.newest)}`):choose('Regionale Daten sind in dieser Ansicht derzeit nicht verfügbar. Verfügbare Saisondaten können weiterhin genutzt werden; fehlende Listen werden beim Lernen gekennzeichnet.','Regional data is currently unavailable in this view. Available seasonal data can still be used; missing lists are labelled in the learning settings.');
 const sources=meta.sources.map(s=>`<li>${link(s.url,english?SOURCE_TITLES_EN[s.url]||s.title:s.title)}</li>`).join('');
 const originalSources=english?`<details><summary>Original source titles</summary><ul data-name-content>${meta.sources.map(s=>`<li>${link(s.url,s.title)}</li>`).join('')}</ul></details>`:'';
 const seasonalCoverage=seasonal?.regions?['DE','NL','GB'].map(code=>{
  const entries=seasonal.regions.filter(r=>r.code===code||r.code.startsWith(code+'-'));
  const count=entries.filter(r=>Object.values(r.seasons).some(s=>s.sample>0)).length;
  const supported=entries.filter(r=>['winter','spring','summer','autumn'].every(k=>r.seasons[k]?.sample>=300&&r.seasons[k]?.years>=3)).length;
  return `${choose(...({DE:['Deutschland','Germany'],NL:['Niederlande','Netherlands'],GB:['Vereinigtes Königreich','United Kingdom']})[code])}: ${count} ${choose(`${count===1?'Gebiet':'Gebiete'} mit historischen Stichproben, davon`,`${count===1?'area':'areas'} with historical samples, of which`)} ${supported} ${choose('in allen vier Jahreszeiten ausreichend belegt','have sufficient samples in all four seasons')}`;
 }).join('; '):'';
 const seasonalIntro=seasonal?.dataset?esc(seasonalDatasetText(seasonal.dataset,english))+'. '+esc(seasonalCoverage)+'. ':choose('Saisonale Daten sind derzeit nicht verfügbar. ','Seasonal data is currently unavailable. ');
 const credit=seasonal?.credit;
 const ebirdReferences=credit?`<h3>${choose('eBird-Daten und Danksagung','eBird data and acknowledgement')}</h3><p>${esc(choose(credit.acknowledgement.de,credit.acknowledgement.en))}</p><ul><li><span lang="en">${esc(credit.datasetCitation)}</span> · ${link(credit.dataSourceURL,choose('EBD-Datenquelle','EBD data source'))}</li><li><span lang="en">${link(credit.primaryReference.url,credit.primaryReference.citation)}</span></li></ul>`:'';
 const blocks=[
 ['scope',choose('Artenbestand und Datenstand','Species coverage and data version'),
  `<p>${choose('Der Katalog vereinigt eBird-Artennachweise aus Deutschland, den Niederlanden und UK einschließlich historischer Seltenheiten und behält die ursprüngliche deutsche Auswahl bei. Die Taxonomie bleibt auf v2025 festgelegt. Nachweise sind weder Brutstatus noch ein Beleg für eine etablierte Population.','The catalogue combines eBird species records from Germany, the Netherlands and the UK, including historical rarities, and retains the original German selection. Taxonomy is pinned to v2025. Occurrence records establish neither breeding status nor a self-sustaining population.')}</p><p>${download('catalog-review.json',choose('Katalogstand, Länderabdeckung und ausgeschlossene Quelltaxa (JSON)','Catalogue version, country coverage and excluded source taxa (JSON)'))}</p>`+
  `<p>${choose('Vorkommensstatus sind redaktionelle Einordnungen, keine Häufigkeitsrangliste oder Gefährdungsbewertung. Brutstatus beziehen sich auf Deutschland; „Rastvogel“ bezeichnet die Nutzung Deutschlands außerhalb der Brutzeit und bedeutet nicht automatisch „Wintergast“.','Occurrence statuses are editorial categories, not abundance rankings or conservation assessments. Breeding statuses refer to Germany; a non-breeding visitor is not automatically a winter visitor.')}</p>`+
  `<p>${choose('Ursprüngliche Datenaufbereitung','Original dataset prepared')}: ${built}. ${choose('Namensmatrix vom 30. Oktober 2025, geprüft gegen die offizielle eBird-Taxonomie v2025-4 (April 2026). Der Bestand wird nicht automatisch auf eine neue Taxonomie umgestellt. Sonderfälle und Zusammenfassungen sind bei der jeweiligen Art erläutert.','Names use the workbook dated 30 October 2025, checked against the official eBird taxonomy v2025-4 (April 2026). The dataset is not automatically migrated to a newer taxonomy. Exceptions and taxonomic combinations are explained in the species details.')}</p>`],
 ['names',choose('Sprachen, Namen und Codes','Languages, names and codes'),
  `<p>${choose('Verfügbare Namensarten','Available name types')}: ${languages}. ${choose('Oberflächensprache sowie Namen für Frage und Antwort werden unabhängig gewählt. Auch die binomialen wissenschaftlichen Namen lassen sich in beiden Richtungen üben. Im Nachschlagen sind Titel, Sortierung und weitere Namenssprachen unabhängig vom Land wählbar. Fehlt der Titelname, erscheint der wissenschaftliche Name; Lernantworten verwenden keinen Sprachersatz.','The interface language and names for questions and answers are selected independently. Binomial scientific names can be practised in either direction. Lookup titles, sorting and additional name languages are independent of country. A missing title uses the scientific name; study answers never substitute another language.')}</p>`+
  `<p>${choose('Deutsche, englische, wissenschaftliche und niederländische Namen sowie Arten-IDs und Quick Find Codes stammen aus der offiziellen eBird-Taxonomie beziehungsweise ihrer mehrsprachigen Namensmatrix. Der englische US-Hauptname und abweichende britische Namen werden angezeigt und als englische Antwort akzeptiert. Niederländische Namen erweitern weder Artenbestand noch Taxonomie.','German, English, scientific and Dutch names, species IDs and Quick Find Codes come from the official eBird taxonomy and its multilingual name matrix. The US English main name and any different British name are shown and accepted as English answers. Dutch names change neither the species selection nor the taxonomy.')}</p>`+
  `<p>${choose(`Für ${germanNamesMeta.speciesCount||0} Arten sind zusätzlich belegte deutsche Namensvarianten hinterlegt. Aktuelle eindeutige Alternativnamen werden als deutsche Antwort akzeptiert; historische und mehrdeutige Namen bleiben Zusatzinformationen. Auch diese Varianten werden bei der Suche gefunden. Namen und originale Quellen- und Bildtitel bleiben in ihrer jeweiligen Sprache; erklärende Begleittexte werden im englischen UI übersetzt.`,`Documented German name variants are provided for ${germanNamesMeta.speciesCount||0} species. Current unambiguous alternatives are accepted as German answers; historical and ambiguous names are shown for reference. These variants are also searchable. Names and original source/image titles retain their language; explanatory notes are translated in the English interface.`)}</p>`+
  `<p>${choose('eBird-Kurzcodes stammen aus der offiziellen Codetabelle vom 27. Oktober 2026. Namensbasierte Quick Find Codes und Banding Codes werden akzeptiert. Zum Lernen wird das Kürzel mit den wenigsten passenden Arten weltweit verwendet; bei Gleichstand hat der Banding Code Vorrang. Mehrdeutige Codes können weiterhin vorkommen; die Suche zeigt alle Treffer im Katalog. Beim Grauschnäpper bleiben wegen einer geänderten Artabgrenzung die offiziellen Codes von 2025 erhalten. Wissenschaftliche Quick Codes werden nicht verwendet.','eBird entry codes use the official code table dated 27 October 2026. Common-name Quick Find Codes and banding codes are accepted. Learning uses the code matching the fewest species worldwide, preferring the banding code on ties. Codes can still be ambiguous; search shows all catalogue matches. Spotted Flycatcher retains the official 2025 codes because its taxonomic concept changed. Scientific-name Quick Codes are not used.')}</p>`+
  `<p>${download('languages/nl.json',choose('Niederländische Namen und Herkunft (JSON)','Dutch names and provenance (JSON)'))} · ${download('german-names.json',choose('Deutsche Namensvarianten und Quellen (JSON)','German name variants and sources (JSON)'))}</p>`],
 ['regions',choose('Regionale Artenauswahl mit eBird','Regional species selection with eBird'),
  `<p>${countryCoverage||choose('Die unterstützten Länder und Regionen erscheinen in den Lerneinstellungen, sobald die regionalen Daten geladen sind','Supported countries and regions appear in the study settings when regional data is available')}. ${choose('Die Gebietsstruktur und Namen folgen eBird. Land, Region beziehungsweise Landesteil und gegebenenfalls lokale Region werden nacheinander gewählt.','Area names and hierarchy follow eBird. Choose a country, then a region or constituent country, and a local region where available.')}</p>`+
  `<p>${choose(`„In den letzten 30 Tagen gemeldet“ verwendet die jüngsten eBird-Meldungen dieses Zeitfensters; „Alle regionalen Nachweise“ verwendet die Gesamt-Nachweisliste. Beide filtern nur die vorhandenen ${f.species} Lernarten. Mehr eBird-Taxa bedeuten nicht automatisch mehr verfügbare Lernarten. Aktuelle Meldungen sind keine Häufigkeitsrangliste oder Sichtungsgarantie; Gesamtlisten können historische Seltenheiten enthalten. Die vorhandenen Deutschland-Statusangaben erscheinen nur bei einer deutschen Auswahl.`,`“Reported in the last 30 days” uses recent eBird reports in that time window; “All regional records” uses the all-time list. Both only filter the existing ${f.species} learning species. Additional eBird taxa do not automatically add learning species. Recent reports are not abundance rankings or a promise of sightings; all-time lists can include historical rarities. The retained German status statements are displayed only for German selections.`)}</p>`+
  `<p>${choose('Ein täglicher Abruf ist über GitHub Actions eingeplant; Aktualisierungen können verspätet eintreffen oder ausfallen. Bei Fehlern bleibt pro Liste nach Möglichkeit der letzte gültige Stand erhalten. Fehlt die gewählte Liste oder ist sie leer, stehen daraus keine neuen Ziele oder eigenen Runden zur Verfügung. Fällige Wiederholungen bereits begonnener Ziele bleiben in der gewählten Lernrichtung und Methode unabhängig von der aktuellen Artenauswahl verfügbar. Ein über drei Tage alter Stand wird bei der Auswahl gekennzeichnet.','A daily refresh is scheduled through GitHub Actions; updates may be delayed or fail. Where possible, each failed list retains its last valid snapshot. Missing or empty selected lists provide no new targets or custom rounds from that selection. Due reviews of started targets remain available in the selected learning direction and method regardless of the current species selection. Lists older than three days are flagged in the selection.')}</p>`+
  `<p>${seasonalIntro}${choose('Die saisonalen Häufigkeitsstufen beruhen auf lokal aufbereiteten EBD-Daten vollständiger Checklisten. Geteilte Listen werden einmal gezählt. EBD wird nach neuen manuellen Downloads aktualisiert; die täglichen API-Meldungen werden unabhängig davon ergänzt. Fehlende oder unzureichende Saisondaten werden durch die regionale Artenliste ersetzt und ausdrücklich gekennzeichnet. Häufig bedeutet mindestens 10 %, mittel 1 bis unter 10 %, selten über 0 bis unter 1 % der vollständigen Listen. Häufig und mittel sind standardmäßig aktiv. Nullwerte oder fehlende Nachweise werden nicht als selten eingestuft; Meldehäufigkeit ist keine Bestandsgröße. Aktuelle Besonderheiten werden automatisch ergänzt und sind gültige bemerkenswerte eBird-Nachweise, höchstens 14 Tage ab Beobachtung; Snapshots über drei Tage werden nicht verwendet. Jede neue Lernrunde verwendet ein ausgewähltes Land oder eine Region. Standard ist „Deutschland – gesamt“ mit den saisonalen Stufen häufig und mittel. Länderlisten verwenden den erweiterten geprüften Katalog; nicht auf v2025-Arten abbildbare Quelltaxa werden im Katalogbericht ausgewiesen. Arten- und Namenssprachenfilter bleiben wirksam, Lernstandsfilter nur für eigene Runden. Laufende und pausierte Runden behalten ihre Auswahl und Meldungsdaten vom Start. Neue Runden prüfen die Gültigkeit erneut.','Seasonal frequency groups use locally processed EBD complete-checklist data. Shared lists count once. EBD is updated after new manual downloads; daily API reports are added independently. Missing or insufficient seasonal data fall back to the regional list, explicitly labelled. Frequent means at least 10%, medium 1% to less than 10%, rare above 0% but less than 1% of complete checklists. Frequent and medium are selected by default. Zero/missing reports are not rare; reporting frequency is not population abundance. Current additions are automatic and use valid notable eBird reports, for at most 14 days after observation; snapshots older than three days are not used. Every new learning round uses a selected country or region. The default is Germany — whole country, with seasonal frequent and medium groups. Country lists use the expanded reviewed catalogue; source taxa that cannot be mapped to v2025 species are documented in the catalogue review. Species and name-language filters still apply, progress filters only to custom rounds. Active and paused rounds retain their original selection and report metadata. New rounds check validity again.')} <a href="seasonal-data.html">${choose('Methode, Quellen und Nutzungsbedingungen','Method, sources and terms')}</a></p>`+
  `<p>${download('seasonal-species.json',choose('Saisonale Artenauswahl (JSON)','Seasonal species selection (JSON)'))} · ${download('seasonal-provenance.json',choose('EBD-Herkunft und Methode (JSON)','EBD provenance and method (JSON)'))} · ${download('ebd-terms.txt',choose('EBD-Nutzungsbedingungen','EBD terms of use'))}</p><p class="notice">${esc(freshness)}</p><p>${download('regions.json',choose('Regionale Artenlisten und Zeitstempel (JSON)','Regional species lists and timestamps (JSON)'))}</p>`],
 ['pictures',choose('Bilder und Nachweise','Pictures and credits'),
  `<p>${choose(`Die App liefert ${f.photoCount} Fotos und ${f.illustrationCount} historische wissenschaftliche Illustrationen aus Wikimedia Commons und iNaturalist mit. Beschriftete Fotos zeigen bei ${f.photoComparisons} Arten beide Geschlechter; bei ${f.illustrationComparisons} Arten ergänzen gekennzeichnete Illustrationen den Vergleich. Zuordnung und Figuren sind durch Quellenbeschreibung, Originallegende oder explizite iNaturalist-Geschlechtsannotation belegt. Bilder sind nicht maßstabsgetreu; Gefieder kann von Alter, Jahreszeit und Unterart abhängen. Historische Illustrationen sind idealisierte Darstellungen.`,`The app includes ${f.photoCount} photographs and ${f.illustrationCount} historical scientific illustrations from Wikimedia Commons and iNaturalist. Labelled photographs show both sexes for ${f.photoComparisons} species; labelled illustrations supplement the comparison for ${f.illustrationComparisons} species. Assignments and figures are supported by the source description, original caption or explicit iNaturalist sex annotation. Images are not to scale; plumage may vary with age, season and subspecies. Historical illustrations are idealised depictions.`)}</p>`+
  `<p>${choose('Jedes Bild hat einen eigenen Bildnachweis mit Urheber, Original-Link und gültiger Lizenz. Im Nachschlagen erscheinen Bilder nach Aktivierung von „Artenbilder“. Beim Lernen erscheinen Bilder nur mit aktivierter Bildoption: in der Vorstellung neuer Ziele und nach der Bewertung, bei Karteikarten nach der Selbsteinschätzung. Für Arten ohne lokales Bild und bei Ladefehlern gibt es einen Link zur artbezogenen eBird-Galerie.','Each image has its own credit with author, original link and applicable licence. Lookup pictures appear when “Species pictures” is enabled. With the study picture option enabled, pictures appear when introducing new targets and after grading, including self-assessment for flashcards. For species without a local picture, or if an image cannot load, a species-specific eBird gallery link is available.')}</p>`+
  `<p>${download('photos.json',choose('Vollständige Bildnachweise (JSON)','Complete image credits (JSON)'))} · ${link('https://commons.wikimedia.org/wiki/Commons:Reusing_content_outside_Wikimedia',choose('Wikimedia: Bildnutzung und Lizenzen','Wikimedia: reuse and licences'))}</p>`],
 ['privacy',choose('Speicherung und Netzwerkzugriffe','Storage and network requests'),
  `<p>${choose('Die App speichert Lernstand und Einstellungen lokal im Browser, ohne Cookies oder Benutzerkonto. Name und E-Mail-Adresse werden nicht benötigt.','The app keeps progress and preferences locally in your browser, without cookies or an account. Your name and email address are not required.')}</p>`+
  `<p>${choose('Lernstand und Einheiten liegen in IndexedDB. Beide UI-Sprachen teilen Suche, Filter, Sprachwahl, Lerneinstellungen und Farbschema; ein kurzlebiger Tab-Eintrag erhält beim Sprachwechsel die aktive Ansicht. Mit aktivierter Bildoption werden Bilder der aktuellen und nächsten zwei Fragen vorbereitet und nach Möglichkeit lokal zwischengespeichert, bei Speicherbeschränkungen nur im Arbeitsspeicher. Cache und alte Übernahmekopien können bis zum Löschen der Websitedaten erhalten bleiben.','Progress and sessions use IndexedDB. Both interfaces share search, filters, languages, study preferences and appearance; a short-lived tab entry preserves the active view during language changes. With pictures enabled, images for the current and next two questions are prepared and cached locally where possible, or only in memory when storage is restricted. Caches and old migration copies may remain until site data is cleared.')}</p>`+
  `<p>${choose('Gespeichert werden Antwortzahlen und Fehler, Lernrichtung, Methodenfamilie, Bestätigungen und Termine sowie das lokale Datum und vorgestellte Ziele fürs Tagesbudget. Frühere Lernwerte bleiben als historische Daten erhalten. Einheiten enthalten außerdem Reihenfolge, Vorstellungsphase, sichtbare Auswahlantworten, Entwurf und zuletzt bewertete Antwort.','Stored data includes answer/error counts, direction, method family, confirmations and review dates, plus the local date and introduced targets for the daily budget. Earlier progress remains as historical data. Sessions also retain order, introduction phase, visible options, drafts and the last graded answer.')} <a href="#lernmethode">${choose('So funktioniert das Lernen','How learning works')}</a></p>`+
  `<p>${choose('App-Dateien, Bilder und regionale Listen kommen vom selben GitHub-Pages-Ursprung. GitHub verarbeitet Verbindungsdaten und protokolliert laut seiner Pages-Dokumentation IP-Adressen zu Sicherheitszwecken. Quizantworten und Lernstände werden nicht zentral übertragen. Die App nutzt keine Analytics, Tracking-Dienste, externen Schriftarten oder automatische Standortabfrage. Externe Quellen, Lizenzen und Galerien werden erst beim Anklicken aufgerufen.','App files, images and regional lists come from the same GitHub Pages origin. GitHub processes connection data and, according to its Pages documentation, logs IP addresses for security. Quiz answers and progress are not sent to a central database. The app uses no analytics, tracking services, external fonts or automatic location lookup. External sources, licences and galleries are requested only when you follow their links.')}</p>`+
  `<p>${link('https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection',choose('GitHub Pages: Datenerfassung','GitHub Pages: data collection'))} · ${link('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement',choose('GitHub: Datenschutzerklärung','GitHub: privacy statement'))}</p>`+
  `<p>${choose('Nur GitHub Actions ruft die eBird-API auf, nicht dein Browser. Der Schlüssel bleibt ein GitHub Actions Secret. Öffentliche Dateien enthalten Arten-IDs, Gebiete, Anzahlen und Zeitstempel; saisonale EBD-Dateien enthalten abgeleitete Artengruppen und Stichprobenzahlen. Aktuelle Ergänzungen nennen je Gebiet und Art das jüngste berücksichtigte Beobachtungs- und Ablaufdatum. Vollständige Beobachtungen, Checklisten-IDs, Beobachternamen, Koordinaten und genaue Fundorte werden nicht veröffentlicht.','The eBird API is called by GitHub Actions, not by your browser. The key stays a GitHub Actions secret. Public files contain species IDs, areas, counts and timestamps; seasonal EBD files contain derived species groups and sample counts. Current additions give the latest included observation date and expiry date per area and species. Full observation records, checklist IDs, observer names, coordinates and precise locations are not published.')}</p>`],
 ['backup',choose('Sicherung, Import und Domainwechsel','Backups, import and changing domains'),
  `<p>${choose('Der JSON-Export (Version 2) in der Statistik sichert alle Antwortsprachen und Codes samt Lernrichtungen, Methodennachweisen, Tagesbudget sowie Versions-, Taxonomie- und Exportangaben. Suche, Einstellungen, Einheiten, Entwürfe und Bildcache sind ausgeschlossen. Importiert werden Version 1 und 2; alte Antwortzahlen und Termine bleiben ohne erfundene Richtungs- oder Methodennachweise erhalten. Die Dateiauswahl zeigt zunächst eine Vorschau mit Name, Datum und Umfang. Erst der Ersetzen-Button ersetzt alle Lernwerte und das Tagesbudget und beendet pausierte Einheiten; die Daten werden nicht zusammengeführt. Die Datei wird nur lokal gelesen. Sichere den bisherigen Stand vor Import oder Zurücksetzen. Wenn das Speichern fehlschlägt, bleiben Lernstand und pausierte Einheiten erhalten.','The version-2 JSON export in Statistics covers all supported answer languages and codes, directions, method evidence and daily budget, plus version, taxonomy and export metadata. Search, preferences, sessions, drafts and image caches are excluded. Imports accept versions 1 and 2; old totals and dates are retained without invented direction or method evidence. Selecting a file previews its name, date and scope. Only the Replace button overwrites all progress and the daily budget and ends paused sessions. Records are not merged. Files are read locally, not uploaded. Back up before importing or resetting; if saving fails, progress and paused sessions are retained.')}</p>`+
  `<p>${choose('Browserspeicher ist an den Website-Ursprung gebunden. Bei einem Domainwechsel exportierst du auf der alten Seite und importierst auf der neuen; Einstellungen wählst du dort erneut. Die neue Domain kann den alten Speicher nicht lesen.','Storage is tied to the website origin. When changing domains, export on the old site, import on the new one and choose preferences again. The new domain cannot read the old site’s storage.')}</p>`+
  `<p>${choose('Privatmodus und Browserbereinigung können Lernstände löschen. „Fortschritt zurücksetzen“ entfernt Lernstand, Tagesbudget und aktuelle Einheiten, aber nicht sämtliche Einstellungen, Bildcaches oder Übernahmekopien. Vollständig entfernst du diese über die Websitedaten im Browser. Es gibt keinen geräteübergreifenden Abgleich und keine zugesicherte Offline-Nutzung.','Private browsing and browser cleanup can erase progress. “Reset progress” clears progress, the daily budget and current sessions, but not all preferences, caches or migration copies. Clear site data in the browser to remove all local copies. There is no cross-device sync or guaranteed offline use.')}</p>`],
 ['sources',choose('Quellen und Unabhängigkeit','Sources and independence'),
  `<ul>${sources}</ul>${ebirdReferences}${english?'<p>English link labels describe the sources; linked documents may be in German. Their original titles are available below.</p>':''}${originalSources}<p>${download('species.json',choose('Artenstammdaten (JSON)','Species data (JSON)'))} · ${link('validation.json',choose('Validierungsbericht','Validation report'))}</p><p>${choose('BirdNames DE ist ein unabhängiges Lernangebot und kein Produkt des Cornell Lab oder des DDA. Der Lernbestand ist keine vollständige nationale Nachweisliste.','BirdNames DE is an independent learning app, not a Cornell Lab or DDA product. The learning dataset is not a complete national checklist.')}</p>`],
 ['project',choose('Projekt und Lizenz','Project and licence'),
  `<p>${choose('Der originale Programmcode der App, die Skripte und die Projektkonfiguration stehen unter der MIT-Lizenz (© 2026 DG1TAL). Diese Lizenz gilt nicht für die Arten- und Taxonomiedaten, Namen, Quick Find Codes, regionalen Daten, Fotos oder Illustrationen. Für jedes Bild gelten die bei ihm angegebenen Lizenz- und Urheberhinweise.','The original app code, scripts and project configuration are licensed under the MIT License (© 2026 DG1TAL). This licence does not cover species and taxonomy data, names, Quick Find Codes, regional data, photographs or illustrations. Each image has its own licence and attribution shown alongside it.')}</p>`+
  `<p>${link('https://github.com/dg1tal/birdnamesde',choose('Quellcode auf GitHub','Source code on GitHub'))} · ${link('https://github.com/dg1tal/birdnamesde/blob/main/LICENSE',choose('MIT-Lizenztext','MIT License text'))}</p>`]
 ];
 return `<h1>${choose('Daten & Datenschutz','Data & privacy')}</h1><div class="panel information-page"><p class="data-count"><strong>${f.species} ${choose('Arten','species')}</strong> · eBird/Clements ${esc(meta.taxonomy)}</p><p class="muted">${choose('Angaben geprüft am','Information reviewed on')} ${date(INFO_REVIEWED)}.</p>${blocks.map(([id,title,body])=>`<section aria-labelledby="info-${id}"><h2 id="info-${id}">${title}</h2>${body}</section>`).join('')}</div>`;
}
